CREATE EXTENSION IF NOT EXISTS postgis;
CREATE TABLE sources(id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL,url TEXT NOT NULL,license TEXT,fetched_at TIMESTAMPTZ);
CREATE TABLE regions(id UUID PRIMARY KEY,country_iso2 CHAR(2),name TEXT NOT NULL,center GEOGRAPHY(POINT,4326),boundary GEOMETRY(MULTIPOLYGON,4326),source_id BIGINT REFERENCES sources(id),verified_at TIMESTAMPTZ);
CREATE TABLE varieties(id UUID PRIMARY KEY,name TEXT NOT NULL,species TEXT,source_id BIGINT REFERENCES sources(id));
CREATE TABLE region_varieties(region_id UUID REFERENCES regions(id),variety_id UUID REFERENCES varieties(id),PRIMARY KEY(region_id,variety_id));
CREATE TABLE processing_methods(id BIGSERIAL PRIMARY KEY,name TEXT UNIQUE NOT NULL);
CREATE TABLE terroir_observations(id BIGSERIAL PRIMARY KEY,region_id UUID REFERENCES regions(id),observed_on DATE,temperature_c NUMERIC,rainfall_mm NUMERIC,altitude_m INT,soil_class TEXT,source_id BIGINT REFERENCES sources(id));
CREATE TABLE farms(id UUID PRIMARY KEY,region_id UUID REFERENCES regions(id),name TEXT NOT NULL);
CREATE TABLE coffee_lots(id UUID PRIMARY KEY,farm_id UUID REFERENCES farms(id),variety_id UUID REFERENCES varieties(id),lot_name TEXT NOT NULL,harvest_year INT);
CREATE TABLE competitions(id UUID PRIMARY KEY,name TEXT NOT NULL,year INT NOT NULL,source_id BIGINT REFERENCES sources(id));
CREATE TABLE cupping_results(id BIGSERIAL PRIMARY KEY,lot_id UUID REFERENCES coffee_lots(id),competition_id UUID REFERENCES competitions(id),score NUMERIC(5,2) CHECK(score BETWEEN 0 AND 100),score_method TEXT NOT NULL,source_id BIGINT NOT NULL REFERENCES sources(id),verified_at TIMESTAMPTZ);
CREATE TABLE ingestion_runs(id BIGSERIAL PRIMARY KEY,source_id BIGINT REFERENCES sources(id),started_at TIMESTAMPTZ DEFAULT now(),status TEXT,error TEXT);
CREATE INDEX regions_geo_idx ON regions USING GIST(center);
